# Custom extracted icons as base64 strings
CUSTOM_ICONS = {
    "action_download": "data:image/png;base64,",
    "action_error": "data:image/png;base64,",
    "action_filter": "data:image/png;base64,",
    "action_info": "data:image/png;base64,",
    "action_logout": "data:image/png;base64,",
    "action_notifications": "data:image/png;base64,",
    "action_profile": "data:image/png;base64,",
    "action_refresh": "data:image/png;base64,",
    "action_search": "data:image/png;base64,",
    "action_success": "data:image/png;base64,",
    "action_upload": "data:image/png;base64,",
    "action_warning": "data:image/png;base64,",
    "feature_history": "data:image/png;base64,",
    "feature_live_trainer": "data:image/png;base64,",
    "feature_nutrition": "data:image/png;base64,",
    "feature_supplements": "data:image/png;base64,",
    "feature_video": "data:image/png;base64,",
    "feature_yoga": "data:image/png;base64,",
    "logo_arogya": "data:image/png;base64,",
    "sidebar_history": "data:image/png;base64,",
    "sidebar_home": "data:image/png;base64,",
    "sidebar_live_trainer": "data:image/png;base64,",
    "sidebar_nutrition": "data:image/png;base64,",
    "sidebar_supplements": "data:image/png;base64,",
    "sidebar_video": "data:image/png;base64,",
    "sidebar_yoga": "data:image/png;base64,",
}

def get_custom_icon_html(icon_name: str, size: int = 24) -> str:
    src = CUSTOM_ICONS.get(icon_name, "")
    if not src:
        return ""
    return f'<img src="{src}" width="{size}" height="{size}" style="vertical-align: middle; object-fit: contain;" />'
